// Detecta títulos com BSR piorando ou em zona crítica
const titulos = $input.all().map(i => i.json);
const alertas = [];

for (const t of titulos) {
  const bsr = t.bsr_geral;
  const bsr7d = t.bsr_7d || [];

  if (!bsr) continue;

  // BSR crítico (acima de 100.000)
  if (bsr > 100_000) {
    alertas.push({
      asin: t.asin,
      titulo: t.titulo,
      bsr_atual: bsr,
      motivo: '🔴 BSR crítico — acima de 100.000',
      nivel: 'critico',
    });
    continue;
  }

  // Tendência de piora: BSR atual > média 7d em mais de 25%
  if (bsr7d.length >= 4) {
    const media7d = Math.round(bsr7d.reduce((a, b) => a + b, 0) / bsr7d.length);
    const piorouPct = ((bsr - media7d) / media7d) * 100;
    if (piorouPct > 25) {
      alertas.push({
        asin: t.asin,
        titulo: t.titulo,
        bsr_atual: bsr,
        media_7d: media7d,
        piora_pct: Math.round(piorouPct),
        motivo: `🟡 BSR piorou ${Math.round(piorouPct)}% vs média 7d`,
        nivel: 'atencao',
      });
    }
  }
}

if (alertas.length === 0) {
  // Nenhum alerta — retorna sinal de skip
  return [{ json: { sem_alertas: true, verificado_em: new Date().toISOString() } }];
}

return alertas.map(a => ({ json: a }));

const alertas = $input.all().map(i => i.json);
const criticos = alertas.filter(a => a.nivel === 'critico');
const atencao  = alertas.filter(a => a.nivel === 'atencao');

let msg = `📊 *KindleRanker — Alerta BSR*\n`;
msg += `_${new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' })}_\n\n`;

if (criticos.length > 0) {
  msg += `*⚠️ CRÍTICOS (${criticos.length})*\n`;
  for (const a of criticos) {
    const nome = a.titulo.length > 40 ? a.titulo.slice(0, 40) + '…' : a.titulo;
    msg += `• ${nome}\n  BSR: #${a.bsr_atual.toLocaleString('pt-BR')} — ${a.motivo}\n`;
  }
  msg += '\n';
}

if (atencao.length > 0) {
  msg += `*🟡 ATENÇÃO (${atencao.length})*\n`;
  for (const a of atencao) {
    const nome = a.titulo.length > 40 ? a.titulo.slice(0, 40) + '…' : a.titulo;
    msg += `• ${nome}\n  BSR: #${a.bsr_atual.toLocaleString('pt-BR')} (+${a.piora_pct}%)\n`;
  }
  msg += '\n';
}

msg += `🔗 Ver dashboard: ${$env.DASHBOARD_URL}`;

return [{ json: { mensagem: msg, total_alertas: alertas.length, criticos: criticos.length } }];
